export function resolveName(name, nodes, aliases) {
  let target = name;
  const visited = new Set();

  while (true) {
    if (Object.hasOwn(nodes, target)) return target;
    if (!Object.hasOwn(aliases, target)) throw new Error('Unknown node: ' + target);
    if (visited.has(target)) throw new Error('Alias cycle: ' + target);
    visited.add(target);
    target = aliases[target];
  }
}
